/// <summary>
/// This class handles the dialog for updating the transfer order extract screen route, routestop, confirmshipdate
/// </summary>
public class METTransferOrderExtractScreenModifyDialog
{
    protected Dialog        dialog;
    protected DialogField   dlgShippingDateConfirmed, dlgRoute, dlgRouteStopNum;//, dlgUpdateStatus;

    private InventTransferShipDate      shippingDateConfirmed;
    private METRoute                    route;
    private METRouteStopNum             routeStopNum;

    boolean                             updateInventTransferTableExt;
    
}

Method.Source:
    /// <summary>
    /// Runs the logic
    /// </summary>
    /// <param name = "_args">arguments</param>
    public static void main(Args _args)
    {
        METTransferOrderExtractScreenModifyDialog   dialogOrderExtractScreen;
        FormRun                             formRun = _args.caller();
        FormDataSource                      metInventTransferTableExt_ds    = formRun.dataSource(formDataSourceStr(METTransferOrderExtractScreen, METInventTransferTableExt));
        FormDataSource                      inventTransferTable_ds          = formRun.dataSource(formDataSourceStr(METTransferOrderExtractScreen, InventTransferTable));
        METInventTransferTableExt           metInventTransferTableExt;
        Dialog                              dialog;
        Map                                 map = formRun.getSelectedRecordsMap();
        container                           transferTableCon;
        InventTransferTable                 inventTransferTable;

        dialogOrderExtractScreen    = new METTransferOrderExtractScreenModifyDialog();
         
        dialog = dialogOrderExtractScreen.dialog(metInventTransferTableExt, map);

        //The code will only be executed if the user click on Yes
        if (dialog.run())
        {
            dialogOrderExtractScreen.getFromDialog();
            if (dialogOrderExtractScreen.validate())
            {
                MapEnumerator mapEnumerator = map.getEnumerator();
                while (mapEnumerator.moveNext())
                {
                    RefRecId            recId = mapEnumerator.currentKey();
                    InventTransferId    value = mapEnumerator.currentValue();

                    inventTransferTable = InventTransferTable::find(value);
                    metInventTransferTableExt = inventTransferTable.metInventTransferTableExt();

                    if (!conFind(transferTableCon, metInventTransferTableExt.InventTransferTable))
                    {
                        //Call Method which will be used to create the Dialog
                        dialogOrderExtractScreen.updateOrderExtractScreenRec(inventTransferTable, metInventTransferTableExt);
                        transferTableCon += metInventTransferTableExt.InventTransferTable;

                        METOrderShipmentLoadCreation    orderShipmentLoadCreation = METOrderShipmentLoadCreation::construct(METOrderTransactionType::TransferOrder, value);
                        orderShipmentLoadCreation.createShippmentLoad(false, false);
                    }
                }
                metInventTransferTableExt_ds.executeQuery();
                inventTransferTable_ds.executeQuery();
            }
        }

    }

    /// <summary>
    /// Updates <c>InventTransferTable</c> with parameters.
    /// </summary>
    /// <param name = "_inventTransferTableExt">InventTransferTable buffer</param>
    private void updateOrderExtractScreenRec(InventTransferTable    _inventTransferTable, METInventTransferTableExt _inventTransferTableExt)
    {
        #OCCRetryCount
        InventTransferLine                  inventTransferLine;
        
        try
        {
            ttsbegin;

            _inventTransferTable.selectForUpdate(true);
            _inventTransferTableExt.selectForUpdate(true);
  
            if (route)
            {
                if (_inventTransferTableExt.Route != route)
                {
                    _inventTransferTableExt.route = route;
                    updateInventTransferTableExt = true;
                }
            }

            if (routeStopNum)
            {
                if (_inventTransferTableExt.routeStopNum != routeStopNum)
                {
                    _inventTransferTableExt.routeStopNum = routeStopNUm;
                    updateInventTransferTableExt = true;
                }
            }

            if (shippingDateConfirmed != dateNull())
            {
                if (_inventTransferTable &&
                    _inventTransferTable.ShipDate != shippingDateConfirmed)
                {
                    _inventTransferTable.ShipDate = shippingDateConfirmed;
                    _inventTransferTable.doUpdate();

                    inventTransferLine.skipDataMethods(true);
                    update_recordset inventTransferLine
                    setting ShipDate = shippingDateConfirmed
                    where inventTransferLine.TransferId == _inventTransferTable.TransferId
                    && inventTransferLine.ShipDate != ShippingDateConfirmed;
                }
            }

            if (updateInventTransferTableExt)
            {
                _inventTransferTableExt.update();
                info(StrFmt("@MET:TransferOrderExtractScreenUpdateInfo", _inventTransferTable.TransferId));
            }
               
            ttscommit;

        }
        catch (Exception::Error)
        {
            error("@MET:METBulkUpdateError");
        }

        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
                
       
    }

    /// <summary>
    /// Validate dialog parameters.
    /// </summary>
    /// <returns>true if validated successfully; otherwise false</returns>
    protected boolean validate()
    {
       boolean     ret = true;
        //CS - CB715_TransferOrderExtract - PS
        int         lenRoute        = strLen(route);
        int         posRoute        = lenRoute;
        str         lastFourDigit   = subStr(route, posRoute, -4);
        //CE - CB715_TransferOrderExtract - PS

        if (route == '' && routeStopNum == 0 && shippingDateConfirmed == dateNull())
        {
            ret = checkFailed("@MET:UpdateCancelled");
        }

        if (shippingDateConfirmed != dateNull() && shippingDateConfirmed < DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
        {
            throw error("@MET:ShipDateNotConfirmed");
        }

        if (routeStopNum != 0)
        {
            int     lenRouteStop    = strLen(int2Str(routeStopNum));

            if (lenRouteStop > 2)
            {
                throw error("@MET:InvalidFormatRouteStop99");
            }
        }

        return ret;
    }

    /// <summary>
    /// Builds the dialog.
    /// </summary>
    /// <param name = "_inventTransferTableExt">table record used to set initial values</param>
    /// <returns>The dialog</returns>
    protected Dialog dialog(METInventTransferTableExt _inventTransferTableExt, Map  _map)
    {
        //Create a Dialog with title
        dialog = new Dialog("@MET:METBulkUpdate");
        dlgRoute        = dialog.addField(extendedTypeStr(METRoute), "@SYS4190");
        dlgRoute.value(strFmt("@MET:METStrfmt1",_inventTransferTableExt.Route));

        dlgRouteStopNum   = dialog.addField(extendedTypestr(METRouteStopNum), "@MET:METRouteStop");
        dlgRouteStopNum.value(strFmt("@MET:METStrfmt1",_inventTransferTableExt.RouteStopNum));
        dlgRouteStopNum.limitText(2);
        dlgRouteStopNum.allowEdit(this.isSingleCustomerSelected(_map));

        dlgShippingDateConfirmed  = dialog.addField(extendedTypeStr(InventTransferShipDate), "@MET:METConfirmedShippingDate");
        dlgShippingDateConfirmed.value(InventTransferTable::findRecId(_inventTransferTableExt.InventTransferTable, true).ShipDate);

        //dlgUpdateStatus = dialog.addField(extendedTypeStr(NoYesId), "@SYS32754");

         
        //Create a "Label" do Dialog
        dialog.addText("@MET:METProceed");

        dialog.formBuildDesign().dialogSize(0);

        return dialog;
    }

    /// <summary>
    /// Retrieves values from the dialog after it is completed.
    /// </summary>
    /// <returns>true if values are retrieved successfully; otherwise, false.</returns>
    protected boolean getFromDialog()
    {
        boolean ret = true;

        shippingDateConfirmed   = dlgShippingDateConfirmed.value();
        route                   = dlgRoute.value();
        routeStopNum            = dlgRouteStopNum.value();
        //updateStatus            = dlgUpdateStatus.value();
        
        return ret;
    }

/// <summary>
/// Instantiates <c>METOrderExtractScreenModifyDialog</c> class
/// </summary>
/// <returns>Instance of <c>METOrderExtractScreenModifyDialog</c> class</returns>
public static METOrderExtractScreenModifyDialog construct()
{
    return new METOrderExtractScreenModifyDialog();
}

    /// <summary>
    /// Method checks if multiple customers are selected based on the selected records in the form. If there are multiple customers, the update will be cancelled since Route and Route stop are customer specific.
    /// </summary>
    /// <param name = "_map">Map reference</param>
    /// <returns>Boolean value</returns>
    public boolean isSingleCustomerSelected(Map _map)
    {
        CustAccount customer;
        int64       recId;
        METInventTransferTableExt metInventTransferTableExt;
        InventTransferTable inventTransferTable;
        InventTransferId    value;

        MapEnumerator mapEnumerator = _map.getEnumerator();
        
        while (mapEnumerator.moveNext())
        {
            recId = mapEnumerator.currentKey();
            value = mapEnumerator.currentValue();

            inventTransferTable = InventTransferTable::find(value);
            metInventTransferTableExt = inventTransferTable.metInventTransferTableExt();

            if (!customer)
            {
                customer = metInventTransferTableExt.InternalCustomer;
            }

            if (customer != metInventTransferTableExt.InternalCustomer)
            {
                return false;
            }
        }
        return true;
    }
